 void Setup()=>SetupWindow().ShowDialog();
 W.Window SetupWindow(){
  var frame=new DgxSetupFrame();var root=frame.Root;var dialog=Dialog("Set up ChatGPT Watchdog",DgxSetupFrame.Width,DgxSetupFrame.Height,root);frame.Configure(dialog);
  var restore=Standard(Button("Restore from a backup",()=>{Restore();dialog.Close();}));var warning=DangerCard("This app force-closes ChatGPT","Unsaved work may be lost. Monitoring stays paused during setup.");var welcome=DgxSetupWelcome.Create("ChatGPT Watchdog","monitoring timing",restore,warning);
  var commonOptions=new DgxSetupAppearance(value.Appearance,preferences.CloseToTray,preferences.MinimizeToTray,value.StartWithWindows,preferences.StartMinimized);var options=commonOptions.Panel;var appearance=commonOptions.Appearance;var close=commonOptions.CloseToTray;var minimize=commonOptions.MinimizeToTray;var startup=commonOptions.Startup;var startMin=commonOptions.StartMinimized;startup.IsEnabled=!ReviewEntry.Safe;
  var timing=new C.StackPanel();Heading(timing,"Choose your monitoring timing");var idle=Number(timing,"Inactivity (minutes)",value.IdleMinutes,1,1440);var warn=Number(timing,"Warning (seconds)",value.WarningSeconds,10,600);var postpone=Number(timing,"Postpone countdown (minutes)",value.PostponeMinutes,1,1440);timing.Children.Add(WorkText("New input cancels a warning. Cancel or postpone the countdown to keep ChatGPT open."));
  var finish=DgxSetupFrame.Finish("ChatGPT Watchdog","Use the eye button on the main page to start or pause monitoring. Save important work before starting monitoring.");
  var pages=new W.FrameworkElement[]{welcome,options,timing,finish};int page=0;var back=frame.Back;var next=frame.Next;
  void Show(){frame.Show(page,pages);}

  back.Click+=(_,_)=>{if(page>0){page--;Show();}};next.Click+=(_,_)=>Guard(()=>{var updated=value with{IdleMinutes=int.Parse(idle.Text),WarningSeconds=int.Parse(warn.Text),PostponeMinutes=int.Parse(postpone.Text),Appearance=(string)appearance.SelectedItem,StartWithWindows=startup.IsChecked==true};updated.Validate();if(page<pages.Length-1){page++;Show();return;}using var integration=ReviewEntry.Safe?null:StartupChange.Apply(updated.StartWithWindows,directory);value=store.Save(updated);integration?.Commit();SavePreferences(preferences with{CloseToTray=close.IsChecked==true,MinimizeToTray=minimize.IsChecked==true,StartMinimized=startMin.IsChecked==true});ApplyTheme(value.Appearance);runtime?.Configure(value);SyncTiming();File.WriteAllText(Path.Combine(directory,"setup.json"),"{} ");dialog.DialogResult=true;});runtime?.Pause();Show();return dialog;
