 internal W.Window HelpWindow(){var panel=new C.DockPanel{Margin=new W.Thickness(28)};DgxHelpTypography.Apply(panel);var label=Text("Search help");C.DockPanel.SetDock(label,C.Dock.Top);panel.Children.Add(label);var search=new C.TextBox();System.Windows.Automation.AutomationProperties.SetName(search,"Search help");C.DockPanel.SetDock(search,C.Dock.Top);panel.Children.Add(search);var actions=new C.WrapPanel{HorizontalAlignment=W.HorizontalAlignment.Right,Margin=new W.Thickness(0,18,0,0)};C.DockPanel.SetDock(actions,C.Dock.Bottom);panel.Children.Add(actions);actions.Children.Add(Standard(new C.Button{Content="Close",IsCancel=true}));var topics=new C.ListBox{Width=260,Margin=new W.Thickness(0,0,18,0)};C.ScrollViewer.SetHorizontalScrollBarVisibility(topics,C.ScrollBarVisibility.Disabled);C.DockPanel.SetDock(topics,C.Dock.Left);panel.Children.Add(topics);var article=new DgxHelpArticle();panel.Children.Add(new C.ScrollViewer{Content=article,VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=C.ScrollBarVisibility.Disabled});void Filter(){topics.Items.Clear();foreach(var item in Topics.Where(x=>(x.Key+" "+x.Value).Contains(search.Text,StringComparison.CurrentCultureIgnoreCase)))topics.Items.Add(new C.ListBoxItem{Content=Text(item.Key),Tag=item.Key});topics.SelectedIndex=topics.Items.Count>0?0:-1;if(topics.Items.Count==0)article.Text="No help topics match your search.";}topics.SelectionChanged+=(_,_)=>{if(topics.SelectedItem is C.ListBoxItem item)article.Text=item.Tag+"\n\n"+Topics[(string)item.Tag];};search.TextChanged+=(_,_)=>Filter();Filter();return Dialog("Help & user guide",900,620,panel);} void About()=>AboutWindow().ShowDialog();
