 void StartDemo(){if(warning!=null){warning.Activate();return;}demoNow=0;engine=new(value,0);engine.Tick(0,1,0,"simulated-target");demoNow=value.IdleMinutes*60000L;engine.Tick(demoNow,1,demoNow,"simulated-target");var panel=new C.StackPanel{Margin=new W.Thickness(28)};Heading(panel,"ChatGPT closure warning");panel.Children.Add(WorkText("Simulation only. No application will be closed."));var countdown=Text("",22);countdown.Name="Countdown";panel.Children.Add(countdown);var actions=new C.WrapPanel{HorizontalAlignment=W.HorizontalAlignment.Right,Margin=new W.Thickness(0,24,0,0)};panel.Children.Add(actions);warning=Dialog("Warning preview",520,280,panel);var current=warning;actions.Children.Add(Standard(Button("Postpone",()=>{engine.Postpone(demoNow);current.Close();})));actions.Children.Add(Standard(Button("Cancel",()=>{engine.Cancel(demoNow);current.Close();})));current.Closing+=(_,_)=>{demoTimer.Stop();if(engine.State==WatchState.Warning)engine.Cancel(demoNow);warning=null;};current.Topmost=value.Notifications.AlwaysOnTop;current.Show();DemoTick();demoTimer.Start();}
